using RibbonKit.WinForms;

namespace RibbonKitDesignerConsumer;

internal static class OptionsShellCheck
{
    internal static void Verify(string output)
    {
        Directory.CreateDirectory(output); var evidence = new List<string>();
        foreach (var family in new[] { RibbonBuiltInTheme.Office2019Light, RibbonBuiltInTheme.Office2024Light })
        foreach (var backdrop in new[] { RibbonWindowBackdrop.None, RibbonWindowBackdrop.Mica })
        {
            string scope = family + "-" + backdrop; using var renderer = new RibbonOffice2024Renderer(); using var owner = new RibbonForm { Bounds = new(-16000, -16000, 1200, 700), StartPosition = FormStartPosition.Manual, ShowInTaskbar = false, Backdrop = backdrop }; using var ribbon = new RibbonControl { BuiltInTheme = family, Renderer = renderer, AnimationLevel = RibbonAnimationLevel.None }; owner.Controls.Add(ribbon); owner.Ribbon = ribbon;
            var tab = new RibbonTab { Id = "shell.home", Text = "Home" }; var group = new RibbonGroup { Id = "shell.commands", Text = "Commands" }; var save = new RibbonButtonItem { Id = "shell.save", Text = "Save" }; var undo = new RibbonButtonItem { Id = "shell.undo", Text = "Undo" }; group.Items.AddRange(save, undo); tab.Groups.Add(group); ribbon.Tabs.Add(tab); ribbon.QuickAccessItems.Add(new RibbonQuickAccessReference { Source = save }); ribbon.CommandCatalog.CaptureDefaults(); owner.Show(); Application.DoEvents(); var original = ribbon.Theme; int states = 0;
            var settings = new RibbonOptionsAppearanceSettings { NavigationCornerRadius = 12, NavigationMarkerWidth = 6, DividerWidth = 3, ButtonInset = 2, ButtonBorderWidth = 2, ButtonBorderColor = Color.Navy, ButtonFocusInset = 6, ButtonBackground = new(Color.LightYellow), AccentButtonBackground = new(Color.DarkSlateBlue), HeadingFontSizeIncrement = 8, HeadingMinimumFontSize = 20, HeadingBold = false, HeadingBottomPadding = 20 };
            foreach (var mode in new[] { RibbonLayoutMode.Classic, RibbonLayoutMode.Simplified })
            foreach (var density in new[] { RibbonDensity.Compact, RibbonDensity.Touch })
            {
                ribbon.LayoutMode = mode; ribbon.Density = density; ribbon.Theme = original with { OptionsAppearance = settings };
                using var dialog = Make(ribbon, out var page, out var editor); bool valid = false; int applied = 0, cancelled = 0; string checkpoint = "Original"; page.Applying += (_, e) => e.Cancel = !valid; page.Applied += (_, _) => { applied++; checkpoint = editor.Text; }; page.Cancelled += (_, _) => { cancelled++; editor.Text = checkpoint; };
                dialog.Show(owner); Application.DoEvents(); editor.Focus(); editor.Select(2, 5); var heading = Heading(dialog); int S(int n) => (int)Math.Ceiling(n * dialog.DeviceDpi / 96d);
                Require(heading.Font.SizeInPoints == Math.Max(dialog.Font.SizeInPoints + 8, 20) && !heading.Font.Bold && heading.Padding.Bottom == S(20), "Actual native heading bypassed size/weight/gap settings.");
                var buttons = Descendants(dialog).OfType<Button>().ToDictionary(c => c.Name, c => (Control: c, Handle: c.Handle, Bounds: c.Bounds)); var geometry = Geometry(dialog); nint editorHandle = editor.Handle, dialogHandle = dialog.Handle; var parent = editor.Parent;
                foreach (var name in new[] { "AcceptCustomization", "CancelCustomization", "ApplyCustomization" })
                {
                    var button = buttons[name].Control; using var image = Print(button); Require(image.GetPixel(S(2), image.Height / 2).ToArgb() == Color.Navy.ToArgb(), "Actual button outline bypassed settings."); int bottom = image.Height - S(2) - S(2) - 2; Require(image.GetPixel(image.Width / 2, bottom).ToArgb() == (name == "AcceptCustomization" ? Color.DarkSlateBlue : Color.LightYellow).ToArgb(), "Actual idle button fill bypassed settings."); image.Save(Path.Combine(output, $"{scope}-{mode}-{density}-{name}.png"));
                }
                using (var image = Print(dialog)) image.Save(Path.Combine(output, $"{scope}-{mode}-{density}-options.png"));
                ribbon.Theme = ribbon.Theme with { OptionsAppearance = ResetButtons(settings) }; foreach (var button in buttons.Values) { using var image = Print(button.Control); Require(button.Control.Handle == button.Handle && button.Control.Bounds == button.Bounds && !Has(image, Color.Navy), "Button reset retained outline or replaced native control."); }
                Require(Geometry(dialog).SequenceEqual(geometry) && dialog.Handle == dialogHandle && editor.Handle == editorHandle && ReferenceEquals(parent, editor.Parent) && editor.Text == "Retained shell draft" && editor.SelectionStart == 2 && editor.SelectionLength == 5 && ReferenceEquals(page, dialog.SelectedPage) && ReferenceEquals(dialog.AcceptButton, buttons["AcceptCustomization"].Control) && ReferenceEquals(dialog.CancelButton, buttons["CancelCustomization"].Control), "Button settings changed native state, targets or default/cancel ownership.");
                buttons["ApplyCustomization"].Control.PerformClick(); Require(applied == 0, "Invalid Apply committed."); valid = true; buttons["ApplyCustomization"].Control.PerformClick(); Require(applied == 1, "Apply did not commit once."); editor.Text = "Unapplied draft"; valid = false; buttons["AcceptCustomization"].Control.PerformClick(); Require(dialog.Visible && ReferenceEquals(page, dialog.SelectedPage), "Invalid OK closed or changed the page."); buttons["CancelCustomization"].Control.PerformClick(); Require(cancelled == 1 && checkpoint == "Retained shell draft", "Cancel lost the applied checkpoint.");
                ribbon.Theme = ribbon.Theme with { OptionsAppearance = ResetHeadings(ribbon.Theme.OptionsAppearance!) }; using var restored = Make(ribbon, out _, out _); restored.Show(owner); Application.DoEvents(); var reset = Heading(restored); Require(reset.Font.SizeInPoints == Math.Max(restored.Font.SizeInPoints + 5, 14) && reset.Font.Style == FontStyle.Bold && reset.Padding.Bottom == (int)Math.Ceiling(12 * restored.DeviceDpi / 96d) && ribbon.Theme.OptionsAppearance!.NavigationCornerRadius == 12 && ribbon.Theme.OptionsAppearance.DividerWidth == 3, "Heading reopen/reset changed defaults or accepted navigation."); restored.Close(); states++;
            }
            ribbon.Theme = original with { OptionsAppearance = settings };
            using (var builtIn = new RibbonQuickAccessCustomizationForm(ribbon, "RibbonKit.Shell.Check") { StartPosition = FormStartPosition.Manual, Location = new(-16000, -16000), ShowInTaskbar = false })
            {
                builtIn.Show(owner); Application.DoEvents(); var draft = builtIn.Editor.Session.Draft; draft.QuickAccess.Add(new() { CommandId = undo.Id }); builtIn.Editor.RefreshDraft(); var sources = ribbon.QuickAccessItems.ToArray(); var controls = Descendants(builtIn).Where(c => c is TextBox or ListBox or TreeView or Button).ToDictionary(c => c, c => c.Handle); using var image = Print(builtIn); image.Save(Path.Combine(output, $"{scope}-customization.png")); ribbon.Theme = original;
                Require(ReferenceEquals(draft, builtIn.Editor.Session.Draft) && draft.QuickAccess.Count == 2 && sources.Length == 1 && sources.SequenceEqual(ribbon.QuickAccessItems) && controls.All(p => !p.Key.IsDisposed && p.Key.Handle == p.Value), "Built-in Options lost its pending Undo draft, Save source or native controls."); Descendants(builtIn).OfType<Button>().Single(b => b.Name == "CancelCustomization").PerformClick(); Require(sources.SequenceEqual(ribbon.QuickAccessItems), "Cancel applied the pending customization draft.");
            }
            ribbon.Theme = original with { OptionsAppearance = ResetButtons(settings) }; Require(ribbon.Theme.OptionsAppearance!.HeadingBold == false, "Button member reset cleared headings."); ribbon.Theme = original with { OptionsAppearance = ResetHeadings(settings) }; Require(ribbon.Theme.OptionsAppearance!.ButtonBorderWidth == 2, "Heading member reset cleared buttons."); ribbon.Theme = ribbon.Theme with { OptionsAppearance = null }; Require(ribbon.Theme.OptionsAppearance is null, "Group Reset failed.");
            evidence.Add($"PASS {scope}: effective owner={owner.EffectiveBackdrop}, dpi={ribbon.DeviceDpi}; {states} mode/density states; actual native ordinary/accent button outline/fill and heading font/weight/padding, unchanged button/dialog/editor/native targets and HWND/parent/value/selection/default-cancel owners, invalid Apply/OK and valid Apply/Cancel checkpoints; heading reopen/reset defaults, accepted navigation retention, built-in pending Undo draft/Save source/native control retention and independent/group Reset."); owner.Close();
        }
evidence.Add("Synchronous offscreen public-package checks. Headings use existing construction/load/font/DPI layout, verified on opening/reopening; no live theme coordinator was added. Physical input/IME, actual VS, mixed-monitor, external UIA and visible frame pacing remain separate."); File.WriteAllLines(Path.Combine(output, "result.log"), evidence);
    }
    private static RibbonOptionsAppearanceSettings ResetButtons(RibbonOptionsAppearanceSettings a) => a with { ButtonInset = null, ButtonBorderWidth = null, ButtonBorderColor = Color.Empty, ButtonFocusInset = null, ButtonBackground = null, AccentButtonBackground = null };
    private static RibbonOptionsAppearanceSettings ResetHeadings(RibbonOptionsAppearanceSettings a) => a with { HeadingFontSizeIncrement = null, HeadingMinimumFontSize = null, HeadingBold = null, HeadingBottomPadding = null };
    private static RibbonOptionsDialog Make(RibbonControl ribbon, out RibbonOptionsPage page, out TextBox editor) { var dialog = new RibbonOptionsDialog(ribbon) { StartPosition = FormStartPosition.Manual, Location = new(-16000, -16000), ShowInTaskbar = false }; page = new() { Text = "General", BackColor = ribbon.Theme.Surface }; editor = new() { Text = "Retained shell draft", Bounds = new(12, 12, 220, 24) }; page.Controls.Add(editor); dialog.Pages.Add(page); dialog.Pages.Add(new RibbonOptionsPage { Text = "Advanced" }); return dialog; }
    private static Label Heading(Form form) => Descendants(form).OfType<Label>().Single(c => c.Text == "General" || c.Text == "Quick Access Toolbar");
    private static Bitmap Print(Control control) { var image = new Bitmap(control.Width, control.Height); control.DrawToBitmap(image, new(Point.Empty, image.Size)); return image; }
    private static bool Has(Bitmap image, Color color) => Enumerable.Range(0, image.Height).Any(y => Enumerable.Range(0, image.Width).Any(x => image.GetPixel(x, y).ToArgb() == color.ToArgb()));
    private static IEnumerable<Control> Descendants(Control root) => root.Controls.Cast<Control>().SelectMany(c => new[] { c }.Concat(Descendants(c)));
    private static string[] Geometry(Control root) => Descendants(root).Select(c => c.GetType().Name + ":" + c.Name + ":" + c.Bounds).ToArray();
    private static void Require(bool condition, string message) { if (!condition) throw new InvalidOperationException(message); }
}
